#!/usr/bin/env bash
# shellcheck disable=SC2016 # expectations are single-quoted on purpose (run later by eval)
# Greenfield: the project-mode guard (nothing is written when a command is refused), the state-driven status, the roadmap check,
# the handover gate, reviews, and a scripted walker that follows only `greenfield status` to READY FOR HANDOVER.
# Needs openspec and node. The walker replaces the agent with canned content, so it proves the state machine, not agent quality.
# Usage: tests/greenfield.sh. Exit 0 when every case passes.
set -uo pipefail
PKG="$(cd "$(dirname "$0")/.." && pwd)"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
export OPENSPEC_TELEMETRY=0 GIT_AUTHOR_NAME=t GIT_AUTHOR_EMAIL=t@example.invalid GIT_COMMITTER_NAME=t GIT_COMMITTER_EMAIL=t@example.invalid
unset OPENSPEC_ROOT OPENSPEC_PROJECT_ROOT
PASS=0; FAIL=0; rc=0; out=""
ok()  { PASS=$((PASS+1)); echo "  ok   $*"; }
bad() { FAIL=$((FAIL+1)); echo "  FAIL $*"; }
expect() { if eval "$2"; then ok "$1"; else bad "$1  (rc=$rc)"; fi; }
FX="$PKG/tests/fixtures/greenfield/kitchenbox"
V="node openspec/scripts/verify-task.cjs"
gq() { grep "$@" >/dev/null; }  # like grep -q, but reads all input (no SIGPIPE under pipefail)
J() { node -e 'let v=JSON.parse(require("fs").readFileSync(0,"utf8"));for(const k of process.argv[1].split(".").filter(Boolean))v=v==null?v:v[k];console.log(typeof v==="object"?JSON.stringify(v):v)' "$1"; }
mk() { rm -rf "$1"; mkdir -p "$1"; ( cd "$1" && git init -q && { openspec init --tools none >/dev/null 2>&1 || mkdir -p openspec/changes openspec/specs; } && "$PKG/install.sh" . --harness all >/dev/null 2>&1 && git add -A && git commit -qm init ); }
snap() { ( cd "$1" && find . -path ./.git -prune -o -type f -print0 | sort -z | xargs -0 sha1sum | sha1sum | cut -c1-12 ); }
walk() { ( cd "$1" && node "$PKG/tests/lib/greenfield-walker.cjs" --project . --fixture "$FX" "${@:2}" ); }
src() { mkdir -p "$1/src"; node -e 'let s="";for(let i=0;i<40;i++)s+="export const f"+i+" = (x) => x + "+i+";\n";require("fs").writeFileSync(process.argv[1]+"/src/app.ts",s)' "$1"; }

echo "== guard: an empty repository is a greenfield candidate"
E="$T/empty"; mk "$E"; cd "$E" || exit
expect "mode is greenfield" '[ "$($V mode --json | J mode)" = greenfield ]'
expect "mode --for start and adopt are allowed" '$V mode --for start >/dev/null && $V mode --for adopt >/dev/null'
expect "config files, a README and a lockfile are not code" 'echo "{}" > package.json; echo "export default {};" > vite.config.ts; echo "# x" > README.md; [ "$($V mode --json | J mode)" = greenfield ]'
expect "status asks for the one confirmation" '$V greenfield status | gq "Step: confirm-start"'
s0="$(snap .)"
expect "start without --yes is a dry run: writes nothing" '$V greenfield start --by "Anna" | gq "dry run" && [ "$(snap .)" = "$s0" ]'
expect "greenfield new before the start is refused (exit 6), nothing written" '$V greenfield new exploration >/dev/null 2>&1; rc=$?; [ $rc = 6 ] && [ "$(snap .)" = "$s0" ]'
expect "inputs README is generated by install, about 10 lines" '[ -f openspec/inputs/README.md ] && [ "$(wc -l < openspec/inputs/README.md)" -le 12 ] && grep -q "/spec-green-start" openspec/inputs/README.md'

echo "== guard: brownfield signals refuse every greenfield command and write nothing"
refused_ok() { # dir
  ( cd "$1" || exit; local s; s="$(snap .)"; local r=0
    for c in "greenfield status" "greenfield start --by A --yes" "greenfield new exploration" "greenfield approve spec --by A" "greenfield review spec --reply /dev/null" "roadmap" "handover" "handover --write" "mode --for start"; do
      $V $c >"$T/o.txt" 2>&1; local rc=$?; if [ $rc != 6 ]; then echo "    $c exited $rc"; r=1; fi
    done
    grep -q "spec-adopt" "$T/o.txt" || { echo "    no /spec-adopt alternative in the refusal"; r=1; }
    [ "$(snap .)" = "$s" ] || { echo "    files changed"; r=1; }
    exit $r ); }
B="$T/src"; mk "$B"; src "$B"
expect "source code (40 lines): mode is brownfield" '( cd $B; [ "$($V mode --json | J mode)" = brownfield ] )'
expect "source code: all greenfield commands exit 6, name /spec-adopt, write nothing" 'refused_ok $B'
B="$T/arch"; mk "$B"; mkdir -p "$B/openspec/changes/archive/2026-01-01-old"
expect "archived changes: brownfield, refused, nothing written" '( cd $B; [ "$($V mode --json | J mode)" = brownfield ] ) && refused_ok $B'
B="$T/specs"; mk "$B"; mkdir -p "$B/openspec/specs/billing"; printf '## Purpose\nx\n' > "$B/openspec/specs/billing/spec.md"
expect "living specs without the marker: brownfield, refused" '( cd $B; [ "$($V mode --json | J mode)" = brownfield ] ) && refused_ok $B'
B="$T/chg"; mk "$B"; mkdir -p "$B/openspec/changes/add-x"
expect "an active change without the marker: brownfield, refused" '( cd $B; [ "$($V mode --json | J mode)" = brownfield ] ) && refused_ok $B'
B="$T/hist"; mk "$B"; ( cd "$B" || exit; for f in a b c; do mkdir -p lib; echo "x" > lib/$f.py; done; git add -A; git commit -qm code; git rm -rq lib; git commit -qm gone )
expect "history with 3+ source paths, code since deleted: brownfield, refused" '( cd $B; [ "$($V mode --json | J mode)" = brownfield ] ) && refused_ok $B'
B="$T/ws"; mk "$B"; printf 'specs: ../specs\n' > "$B/openspec/workspace.yaml"
expect "a workspace layout is refused (exit 6) with an explanation" '( cd $B; $V greenfield status > $T/o.txt 2>&1; rc=$?; [ $rc = 6 ] && grep -qi "layout" $T/o.txt )'

echo "== guard: in-progress greenfield, the reverse protection, and implementation"
G="$T/gf"; mk "$G"; cd "$G" || exit
expect "start --yes writes only the marker (and the inputs README if missing)" 'rm -f openspec/inputs/README.md; $V greenfield start --by "Anna Analyst" --yes >/dev/null && [ -f openspec/greenfield.yaml ] && grep -q "confirmed_by: Anna Analyst" openspec/greenfield.yaml'
expect "mode is greenfield-in-progress" '[ "$($V mode --json | J mode)" = greenfield-in-progress ]'
expect "start again is a no-op" 's="$(snap .)"; $V greenfield start --by X --yes | gq "already started" && [ "$(snap .)" = "$s" ]'
expect "/spec-adopt is refused on an in-progress greenfield project (exit 6), nothing written" 's="$(snap .)"; $V mode --for adopt >$T/o.txt 2>&1; rc=$?; [ $rc = 6 ] && grep -q "spec-green-start" $T/o.txt && [ "$(snap .)" = "$s" ]'
expect "status with no inputs: add-inputs, blocked by the analyst" '$V greenfield status --json > $T/s.json; [ "$(J phase < $T/s.json)" = Inputs ] && [ "$(J step < $T/s.json)" = add-inputs ]'
expect "the text ends with Done / Next / Blocked by" '$V greenfield status | tail -n 3 | cut -d: -f1 | paste -sd, | gq "^Done.*Next\|Done,Next\|Blocked by" ; $V greenfield status | gq "^Done:" && $V greenfield status | gq "^Next:" && [ "$($V greenfield status | tail -n 1 | cut -c1-11)" = "Blocked by:" ]'
expect "status is deterministic: two runs give identical output" '[ "$($V greenfield status --json)" = "$($V greenfield status --json)" ]'
rm -f openspec/greenfield.yaml; mkdir -p openspec/greenfield
expect "marker lost but greenfield files exist: in-progress, says the marker is missing; start --yes restores it" '$V mode | gq "greenfield.yaml is missing" && $V greenfield start --by Anna --yes >/dev/null && [ -f openspec/greenfield.yaml ]'

echo "== the walker follows only the status output to READY FOR HANDOVER"
W="$T/walk"; mk "$W"; cd "$W" || exit
rc=0; walk "$W" > "$T/walk.json" 2>"$T/walk.err" || rc=$?
expect "walker: reaches READY with 0 wrong turns" '[ "$(J ready < $T/walk.json)" = true ] && [ "$(J wrong_turns < $T/walk.json)" = 0 ]'
expect "walker: visited the phases in order" 'node -e "const s=JSON.parse(require(\"fs\").readFileSync(\"$T/walk.json\",\"utf8\")).steps;const o=[\"confirm-start\",\"add-inputs\",\"explore\",\"create-questions\",\"answer-questions\",\"write-assumptions\",\"wait-for-client\",\"write-environments\",\"write-understood\",\"approve-understood\",\"propose-foundation\",\"sync-foundation\",\"archive-foundation\",\"propose-capability\",\"review-spec\",\"signoff-spec\",\"plan\",\"review-plan\",\"dry-run\",\"write-handover\"];let i=-1;for(const x of o){const j=s.indexOf(x,i+1);if(j<0){console.error(\"missing \"+x);process.exit(1)}i=j}"'
expect "status says READY FOR HANDOVER and the manifest exists" '$V greenfield status | head -1 | gq "READY FOR HANDOVER" && [ -f openspec/greenfield/handover.md ] && $V handover | head -1 | gq "READY FOR HANDOVER"'
expect "manifest has records, roadmap and the slice, requirement and why table" 'grep -q "^## Records" openspec/greenfield/handover.md && grep -q "^| 1 | skeleton (skeleton)" openspec/greenfield/handover.md && grep -q "^| slice | requirement | why |" openspec/greenfield/handover.md && grep -q "billing/charge-the-weekly-box" openspec/greenfield/handover.md'
expect "every requirement is in a slice" '$V roadmap --json > $T/r.json; [ "$(J ok < $T/r.json)" = true ] && [ "$(J coverage.uncovered < $T/r.json)" = "[]" ]'
expect "next up is the walking skeleton" '[ "$($V roadmap --next)" = skeleton ]'
expect "run logs and packets are not committed (.apply-runs ignores itself)" '[ "$(git status --short --ignored openspec/.apply-runs | cut -c1-2 | head -1)" = "!!" ] || git check-ignore -q openspec/.apply-runs/greenfield/spec-packet.md'
expect "no credential value appears anywhere in the generated files" '! grep -rIE "(password|secret|api[_-]?key)[[:space:]]*[:=][[:space:]]*[A-Za-z0-9]{8,}" openspec/greenfield openspec/specs openspec/roadmap adr >/dev/null 2>&1'
expect "re-running the walker on the finished project does nothing and is still READY" 's="$(snap .)"; walk "$W" > $T/w2.json; [ "$(J ready < $T/w2.json)" = true ] && [ "$(J actions < $T/w2.json)" = 0 ] && [ "$(snap .)" = "$s" ]'
git add -A >/dev/null 2>&1; git commit -qm ready >/dev/null 2>&1
READY="$T/ready"; cp -R "$W" "$READY"

echo "== the walker recovers from mistakes the verifier names (sloppy run)"
S="$T/sloppy"; mk "$S"; cd "$S" || exit
rc=0; walk "$S" --sloppy > "$T/sloppy.json" 2>/dev/null || rc=$?
expect "sloppy: still READY, 0 wrong turns, and at least 2 mistakes were found and repaired by following the status" '[ "$(J ready < $T/sloppy.json)" = true ] && [ "$(J wrong_turns < $T/sloppy.json)" = 0 ] && [ "$(J recovered_mistakes < $T/sloppy.json)" -ge 2 ]'

echo "== the gate: every change after the sign-off sends status back to the phase that is affected"
fresh() { rm -rf "$T/m"; cp -R "$READY" "$T/m"; cd "$T/m" || exit; }
step() { $V greenfield status --json | J step; }
phase() { $V greenfield status --json | J phase; }
fresh
expect "a spec edit after the review makes review and sign-off stale: Review phase, not READY" 'sed -i "s/at least 10 characters/at least 12 characters/;s/of at least 10 characters/of at least 12 characters/" openspec/specs/accounts/spec.md; [ "$(step)" = review-spec ] && ! $V handover >/dev/null'
fresh
expect "an edit of the approved page makes the client approval stale: Questions phase" 'echo "- one more thing." >> openspec/greenfield/understood.md; [ "$(step)" = approve-understood ] && $V greenfield status | gq "stale"'
fresh
expect "a credential in a spec fails the gate and its value is never printed" 'printf "\nThe api_key: Zx9Qw7Rt5Yp3Lm2K is used.\n" >> openspec/specs/billing/spec.md; $V handover > $T/o.txt 2>&1; rc=$?; [ $rc = 1 ] && grep -q "openspec/specs/billing/spec.md" $T/o.txt && ! grep -q "Zx9Qw7Rt5Yp3Lm2K" $T/o.txt && ! $V greenfield status --json | gq "Zx9Qw7Rt5Yp3Lm2K"'
fresh
expect "an env-var name as a value is not a credential" 'printf "\nThe PAYGATE_API_KEY: PAYGATE_API_KEY header is used.\n" >> openspec/greenfield/records/ENV-staging.md; $V handover | head -1 | gq "READY\|The gate\|NOT READY" && ! $V handover --json | J missing | gq no-secrets'
fresh
expect "an invalidated assumption blocks the gate with its re-plan trigger" 'sed -i "s/^status: open/status: invalidated/" openspec/greenfield/records/A-design-freeform.md; $V handover > $T/o.txt; rc=$?; [ $rc = 1 ] && grep -q "re-plan" $T/o.txt && grep -q "a design appears" $T/o.txt'
fresh
expect "a question reopened makes the gate and the phase go back to Questions" 'sed -i "s/^status: answered/status: asked/" openspec/greenfield/records/Q-nfr.md; [ "$(phase)" = Questions ] && [ "$(step)" = wait-for-client ] && $V greenfield status --json | J blocked_by | gq client-answer'
fresh
expect "a missing environment makes the gate name it" 'rm openspec/greenfield/records/ENV-*.md; $V handover > $T/o.txt; grep -q "environments, access owners and roles" $T/o.txt'
fresh
expect "an integration without Failure scenarios fails the gate (named per capability)" 'node -e "const f=\"openspec/specs/notifications/spec.md\";const fs=require(\"fs\");fs.writeFileSync(f,fs.readFileSync(f,\"utf8\").replace(/#### Scenario: Failure: MailPost is unavailable[\s\S]*?(?=### Requirement:)/,\"\"))"; $V handover > $T/o.txt; grep -q "notifications: 1 \"#### Scenario: Failure" $T/o.txt'
fresh
expect "an NFR without a number fails the gate" 'sed -i "7s/.*/The system SHALL be fast./;12s/.*/- **THEN** it is fast/" openspec/specs/non-functional-requirements/spec.md; $V handover > $T/o.txt; grep -q "non-functional-requirements/page-response-time: no measurable target" $T/o.txt'
fresh
expect "an NFR with a percentage and no word after it counts as measurable" 'sed -i "7s/.*/The system SHALL answer 99% of requests./;11s/.*/- **THEN** 99% answer/" openspec/specs/non-functional-requirements/spec.md; $V handover > $T/o.txt; ! grep -q "page-response-time: no measurable" $T/o.txt'
fresh
expect "a non-blocking open question is listed in the manifest and must be in the summary" 'printf -- "---\nid: Q-extra\ntopic: users\nstatus: asked\nblocking: no\nowner: client\n---\n## Question\nWhich tools are power tools?\n\n## Answer\nAsked the client on 2026-10-26, not blocking.\n" > openspec/greenfield/records/Q-extra.md; $V handover > $T/o.txt; grep -q "Q-extra" $T/o.txt; echo "Still open: Q-extra." >> openspec/greenfield/understood.md; $V greenfield approve understood --by "Carl Client" >/dev/null; $V handover --write > $T/o2.txt; grep -q "Q-extra: owner client" openspec/greenfield/handover.md'
fresh
expect "a requirement with no Why fails the gate" 'sed -i "0,/^Why: /{/^Why: /d}" openspec/specs/accounts/spec.md; $V handover > $T/o.txt; grep -q "accounts/register-an-account: no \"Why:\" line" $T/o.txt'

echo "== records: every analyst addition is its own file in greenfield/records/ (parallel branches never collide)"
RC="$T/rc"; mk "$RC"; cd "$RC" || exit
$V greenfield start --by Ann --yes >/dev/null; $V greenfield new exploration >/dev/null
$V greenfield new capability app >/dev/null; mkdir -p openspec/inputs; echo "The client wants a app." > openspec/inputs/brief.md
expect "new questions writes one Q-<topic>.md per topic into records/ (no questions folder, no shared file)" '$V greenfield new questions >/dev/null; [ "$(ls openspec/greenfield/records/Q-*.md | wc -l)" = 9 ] && [ ! -e openspec/greenfield/questions ] && [ ! -e openspec/greenfield/questions.md ]'
expect "running it again changes nothing, and a deleted file comes back alone" 's=$(snap .); $V greenfield new questions >/dev/null; [ "$s" = "$(snap .)" ] && rm openspec/greenfield/records/Q-goals.md && $V greenfield new questions >/dev/null && [ -f openspec/greenfield/records/Q-goals.md ]'
expect "new question <topic> adds one more question file with the given text; a bad name is refused" '$V greenfield new question invoice-numbers --text "Which numbering scheme must invoices follow?" >/dev/null && grep -q "^topic: invoice-numbers" openspec/greenfield/records/Q-invoice-numbers.md && grep -q "Which numbering scheme" openspec/greenfield/records/Q-invoice-numbers.md && ! $V greenfield new question "Bad Name" >/dev/null 2>&1'
expect "status names the added question as open" '$V greenfield status --json | J next.problems | gq "Q-invoice-numbers"'
expect "an assumption is records/A-<slug>.md and an environment is records/ENV-<name>.md" '$V greenfield new assumption a1 --from Q-design >/dev/null && $V greenfield new environment staging >/dev/null && [ -f openspec/greenfield/records/A-a1.md ] && [ -f openspec/greenfield/records/ENV-staging.md ] && [ ! -e openspec/greenfield/assumptions ] && [ ! -e openspec/greenfield/environments ]'
expect "an existing record is not overwritten" 'sed -i "s/^owner: <who verifies it>/owner: kept/" openspec/greenfield/records/A-a1.md; $V greenfield new assumption a1 >$T/o.txt; grep -q "exists, not overwritten" $T/o.txt && grep -q "^owner: kept" openspec/greenfield/records/A-a1.md'
expect "the gate reads the records: the placeholders left in the assumption are named" '$V handover --json > $T/o.json; gq "A-a1: missing verify_by, replan_trigger" $T/o.json'
expect "the exploration note needs only Capability map and Integration inventory" '! grep -q "^## Open questions\|^## Assumptions" openspec/greenfield/exploration.md && ! $V greenfield status | gq "lacks sections"'
git add -A; git commit -qm base
git checkout -q -b ann; $V greenfield new question billing --text "How are invoices numbered?" >/dev/null; $V greenfield new assumption bill-a --from Q-billing >/dev/null; $V greenfield new environment staging-ann >/dev/null; git add -A; git commit -qm "ann: question, assumption, environment"
git checkout -q master 2>/dev/null || git checkout -q main; git checkout -q -b bob; $V greenfield new question shipping --text "Which carriers are allowed?" >/dev/null; $V greenfield new assumption ship-b --from Q-shipping >/dev/null; $V greenfield new environment prod-bob >/dev/null; git add -A; git commit -qm "bob: question, assumption, environment"
git checkout -q ann
expect "two branches that each add a question, an assumption and an environment merge without a conflict" 'git merge -q --no-edit bob >$T/m.txt 2>&1; rc=$?; [ $rc = 0 ] && ! grep -q CONFLICT $T/m.txt'
expect "after the merge both analysts records are present and the status sees them all" '[ -f openspec/greenfield/records/Q-billing.md ] && [ -f openspec/greenfield/records/Q-shipping.md ] && [ -f openspec/greenfield/records/A-bill-a.md ] && [ -f openspec/greenfield/records/A-ship-b.md ] && [ -f openspec/greenfield/records/ENV-staging-ann.md ] && [ -f openspec/greenfield/records/ENV-prod-bob.md ] && $V greenfield status --json | J next.problems | gq "Q-shipping" && $V greenfield status --json | J next.problems | gq "Q-billing"'
cd "$T" || exit

echo "== reviews: independent reviewer only, format enforced, findings drive the next step"
fresh
expect "a reply without VERDICT is rejected (exit 2) and nothing is recorded" 'printf "looks fine to me\n" > $T/bad.txt; s="$(snap .)"; $V greenfield review plan --reply $T/bad.txt > $T/o.txt 2>&1; rc=$?; [ $rc = 2 ] && grep -q "no \"VERDICT" $T/o.txt && [ "$(snap .)" = "$s" ]'
expect "a self-review is refused" '$V greenfield review spec --reviewer self >$T/o.txt 2>&1; rc=$?; [ $rc = 1 ] && grep -q "cannot review it" $T/o.txt'
expect "a waiver needs a reason of 10+ characters" '$V greenfield review spec --reviewer none --reason short >/dev/null 2>&1; rc=$?; [ $rc = 2 ]'
expect "a failing reply (blocker, score 61) records fail and the next step is fix-review-findings" '$V greenfield review spec --reply "$FX/replies/spec-fail.txt" >/dev/null; rc=$?; [ $rc = 1 ] && [ "$(step)" = fix-review-findings ] && $V greenfield status | gq "blocker | subscriptions/skip-a-week"'
expect "a pass with score 79 is recorded as fail" 'printf "VERDICT: pass\nSCORE: 79\n" > $T/s79.txt; $V greenfield review spec --reply $T/s79.txt >/dev/null; grep -q "^verdict: fail" openspec/greenfield/reviews/spec.md'
expect "a pass with a blocker finding is recorded as fail" 'printf "VERDICT: pass\nSCORE: 95\nFINDING: blocker | x | y\n" > $T/s95.txt; $V greenfield review spec --reply $T/s95.txt >/dev/null; grep -q "^verdict: fail" openspec/greenfield/reviews/spec.md'
expect "the round count grows with each review" 'grep -q "^rounds: 4" openspec/greenfield/reviews/spec.md'
expect "sign-off is refused while the review has not passed" '$V greenfield approve spec --by Carl >/dev/null 2>&1; rc=$?; [ $rc = 1 ]'
expect "a waiver is accepted, listed in the manifest and shown as a warning" '$V greenfield review spec --reviewer none --reason "owner accepted the risk, 2026-10-26" >/dev/null && $V greenfield approve spec --by "Carl Client" >/dev/null && $V handover --write >/dev/null; grep -q "Note: spec review waived" openspec/greenfield/handover.md'
fresh
expect "a blocked dry-run sends the analyst back to the client with the blocking unknowns" '$V greenfield review dryrun --reply "$FX/replies/dryrun-blocked.txt" >/dev/null; rc=$?; [ $rc = 1 ] && [ "$(step)" = resolve-unknowns ] && $V greenfield status --json | J blocked_by | gq "time zone"'
expect "the review packet names the reviewer role and the reply format" '$V greenfield review spec --packet | gq "spec-reviewer subagent" && $V greenfield review dryrun --packet | gq "UNKNOWN: blocker"'
expect "the packet is read-only: nothing changes" 's="$(snap .)"; $V greenfield review plan --packet >/dev/null; [ "$(snap .)" = "$s" ]'

echo "== roadmap: the dependency graph and its limits"
SL() { sed -i "$2" "openspec/roadmap/$1.md"; }
rm_check() { fresh; "$@"; $V roadmap --json > "$T/r.json"; }
errs() { J errors < "$T/r.json" | node -e 'console.log(JSON.parse(require("fs").readFileSync(0,"utf8")).map((e)=>e.code).sort().join(" "))'; }
rm_check SL notices 's/depends_on: \[delivery\]/depends_on: [delivery, notices]/'
expect "a self-dependency is an error" 'errs | gq self-dependency'
rm_check SL skeleton 's/depends_on: \[\]/depends_on: [notices]/'
expect "a cycle is an error and names the slices; the skeleton may not depend on anything" 'errs | gq cycle && errs | gq skeleton-dependency && J errors < $T/r.json | gq "notices"'
rm_check SL delivery 's/depends_on: \[skeleton\]/depends_on: [ghost]/'
expect "an unknown dependency is an error" 'errs | gq unknown-dependency'
rm_check SL delivery 's/capabilities: \[delivery-slots\]/capabilities: [delivery-slots, phantom]/'
expect "an unknown capability is an error" 'errs | gq unknown-capability'
rm_check SL delivery 's/capabilities: \[delivery-slots\]/capabilities: [delivery-slots\/nope]/'
expect "an unknown requirement is an error" 'errs | gq unknown-requirement'
rm_check rm -f openspec/roadmap/packing.md
expect "dropping the packing slice leaves an uncovered requirement" 'errs | gq uncovered-requirement'
rm_check SL delivery 's/skeleton: false/skeleton: true/'
expect "two skeletons are an error" 'errs | gq multiple-skeletons'
rm_check SL skeleton 's/skeleton: true/skeleton: false/'
expect "no skeleton is an error" 'errs | gq no-skeleton'
rm_check SL packing 's/depends_on: \[skeleton\]/depends_on: []/'
expect "a slice that does not come after the skeleton is an error" 'errs | gq not-after-skeleton'
rm_check SL notices 's/milestone: m2/milestone: m1/'
rm_check SL skeleton 's/milestone: m1/milestone: m3/'
expect "depending on a later milestone is an error" 'errs | gq milestone-order'
rm_check SL delivery 's/contract_tests: \[delivery-slots\]/contract_tests: []/'
expect "the first slice of an integration must list its contract test" 'errs | gq contract-test-missing'
rm_check SL delivery 's/size: S/size: S/;s/capabilities: \[delivery-slots\]/capabilities: [delivery-slots, packing-list]/'
expect "a slice with 2 capabilities declared S is size-under (needs M)" 'errs | gq size-under'
rm_check SL skeleton 's/capabilities: \[accounts, /capabilities: [accounts, notifications, /'
expect "a thick skeleton (more than 5 requirements) is an error" 'errs | gq skeleton-thick'
rm_check SL skeleton 's/size: L/size: S/'
expect "an L-needing slice declared S is size-under with the reason" 'errs | gq size-under && J errors < $T/r.json | gq "any risk is L"'
rm_check SL delivery 's/^## Acceptance criteria/## Notes/'
expect "a slice without acceptance criteria is an error" 'errs | gq no-acceptance'
rm_check SL delivery 's/size: S/size: Z/'
expect "an invalid size is an error" 'errs | gq bad-size'
rm_check SL delivery 's/^milestone: m2//'
expect "a missing milestone is an error" 'errs | gq no-milestone'
fresh; $V roadmap --json > $T/r.json
expect "the order is topological and stable: skeleton first, then milestone, then id" '[ "$(J order < $T/r.json)" = "[\"skeleton\",\"skip-and-pause\",\"delivery\",\"notices\",\"packing\"]" ]'
fresh
expect "overlapping coverage is only a warning" 'SL packing "s/capabilities: \[packing-list\]/capabilities: [packing-list, accounts\/sign-in]/"; ($V roadmap --json || true) | J warnings | gq overlap'
fresh
expect "a risky integration late in the order is a warning" 'prev=skeleton; for i in 1 2 3 4 5 6 7; do printf -- "---\nid: pad$i\ntitle: p\ncapabilities: [accounts/sign-in]\ndepends_on: [$prev]\nsize: S\nstatus: planned\nmilestone: m1\nskeleton: false\ncontract_tests: []\n---\n## Acceptance criteria\n- x\n" > openspec/roadmap/pad$i.md; prev=pad$i; done; sed -i "s/depends_on: \[skeleton\]/depends_on: [pad7]/" openspec/roadmap/delivery.md; sed -i "s/^risk: none/risk: data/" openspec/greenfield/capabilities/delivery-slots.md; ($V roadmap --json || true) | J warnings | gq risky-late'
fresh
mkdir -p openspec/changes/archive/2026-10-26-slice-skeleton
expect "a slice archived as slice-<id> is done, so its dependents become next up" '$V roadmap --json > $T/r.json; [ "$(J counts.done < $T/r.json)" = 1 ] && [ "$($V roadmap --next | paste -sd,)" = "skip-and-pause,delivery,packing" ]'
expect "a file status behind the changes is a warning, never an error" '$V roadmap --json | J warnings | gq status-stale'
expect "the state becomes implementation once a slice change is applied; greenfield writes are refused, reads work" 'mkdir -p openspec/changes/slice-delivery; printf -- "- [x] 1.1 a\n- [ ] 1.2 b\n" > openspec/changes/slice-delivery/tasks.md; [ "$($V mode --json | J mode)" = implementation ] && s="$(snap .)"; for c in "greenfield new slice x" "greenfield start --by A --yes" "handover --write" "greenfield approve spec --by A" "mode --for adopt"; do $V $c >/dev/null 2>&1; r=$?; [ $r = 6 ] || { echo "    $c exit $r"; exit 1; }; done; [ "$(snap .)" = "$s" ] && $V roadmap >/dev/null && $V greenfield status | gq "Phase: Implementation" && $V greenfield status | gq "/spec-green-next"'

echo "== spec-only and slice changes in the existing verifier"
fresh
mkdir -p openspec/changes/slice-x; printf 'Slice: x\n\n## Why\nx\n' > openspec/changes/slice-x/proposal.md; printf 'schema: wingman-spec\nskip_specs: true\n' > openspec/changes/slice-x/.openspec.yaml
mkdir -p openspec/changes/slice-x/specs/billing; printf '## ADDED Requirements\n' > openspec/changes/slice-x/specs/billing/spec.md; printf -- '- [ ] 1.1 a\n' > openspec/changes/slice-x/tasks.md
expect "a slice change that carries delta specs fails lint (slice-with-specs)" '($V lint slice-x 2>/dev/null || true) | gq "slice-with-specs"'
expect "a slice change needs neither an Edge cases section nor the full design (a slice builds existing specs)" 'mkdir -p openspec/changes/slice-y/adrs; printf "Slice: y\nSize: L\nRisk: security\n\n## Why\nx\n" > openspec/changes/slice-y/proposal.md; printf "schema: wingman-spec\nskip_specs: true\n" > openspec/changes/slice-y/.openspec.yaml; printf "## Implementation guide\nx\n\n## Pitfalls\nx\n" > openspec/changes/slice-y/design.md; printf "This change: y\nFits: z\n" > openspec/changes/slice-y/app-map.md; printf -- "- [ ] 1.1 a\n" > openspec/changes/slice-y/tasks.md; out="$( ($V lint slice-y 2>/dev/null || true) )"; ! printf "%s" "$out" | gq "\"kind\": \"edge-cases\"" && ! printf "%s" "$out" | gq "size-artifacts"'
expect "a normal Size: L change still needs Edge cases and the full design" 'mkdir -p openspec/changes/big/specs/big; printf "Size: L\nRisk: security\n\n## Why\nx\n" > openspec/changes/big/proposal.md; printf "schema: wingman-spec\n" > openspec/changes/big/.openspec.yaml; printf "## Implementation guide\nx\n" > openspec/changes/big/design.md; printf "This change: y\nFits: z\n" > openspec/changes/big/app-map.md; printf "## ADDED Requirements\n\n### Requirement: A\nThe system SHALL do a.\n\n#### Scenario: a\n- **WHEN** x\n- **THEN** y\n" > openspec/changes/big/specs/big/spec.md; printf -- "- [ ] 1.1 a\n" > openspec/changes/big/tasks.md; out="$( ($V lint big 2>/dev/null || true) )"; printf "%s" "$out" | gq "edge-cases" && printf "%s" "$out" | gq "size-artifacts"'
expect "size on a spec-only change is ok and says so" 'mkdir -p openspec/changes/so/specs/so; printf "Kind: spec-only\n\n## Why\nx\n" > openspec/changes/so/proposal.md; printf "## Purpose\nSomething long enough to be a real purpose statement here.\n\n## ADDED Requirements\n\n### Requirement: A\nThe system SHALL do a.\n\n#### Scenario: a\n- **WHEN** x\n- **THEN** y\n" > openspec/changes/so/specs/so/spec.md; printf -- "- [x] 1.1 Spec-only change: nothing to implement\n" > openspec/changes/so/tasks.md; $V size so | gq "\"kind\": \"spec-only\""'

echo "== install and harness"
cd "$W" || exit
for f in spec-green-start spec-green-next spec-green-plan; do expect "command $f is rendered for cursor, claude and codex" '[ -f .cursor/commands/'$f'.md ] && [ -f .claude/commands/'$f'.md ] && ls .codex 2>/dev/null | gq . ; true'; done
expect "the spec-reviewer agent is rendered for all three tools and read-only" '[ -f .codex/agents/spec-reviewer.toml ] && grep -rl "^name: spec-reviewer" .cursor/agents .claude/agents >/dev/null 2>&1 && grep -q "^readonly: true" .cursor/agents/spec-reviewer.md'
expect "/spec-adopt runs the mode guard first" 'grep -q "mode --for adopt" .cursor/commands/spec-adopt.md'
expect "/spec-green-start runs only status, never a phase by itself" 'grep -q "greenfield status" .cursor/commands/spec-green-start.md && grep -q "Done" .cursor/commands/spec-green-start.md && grep -q "Blocked by" .cursor/commands/spec-green-start.md'
expect "an install into a brownfield project leaves no inputs folder" 'B2="$T/bf-install"; mkdir -p "$B2"; ( cd "$B2" && git init -q && { openspec init --tools none >/dev/null 2>&1 || mkdir -p openspec/changes openspec/specs; } && mkdir src && node -e "let s=\"\";for(let i=0;i<40;i++)s+=\"export const f\"+i+\" = 1;\n\";require(\"fs\").writeFileSync(\"src/a.ts\",s)" && "$PKG/install.sh" . --harness cursor >/dev/null 2>&1 ); [ ! -d "$B2/openspec/inputs" ]'

echo
echo "greenfield: $PASS passed, $FAIL failed"
[ "$FAIL" = 0 ]
